# monolith.map -- the brutalist test level. Edit while the game runs: it reloads on save.
#
# Format: one statement per line. Units are meters, +Y is up, the player starts near
# (0, 0, 90) looking toward -Z. All boxes are axis-aligned concrete.
#
#   # comment                      '#' starts a comment (anywhere outside "quotes")
#   group "name"                   following primitives belong to this group, until the next
#                                  group (max 63 characters, no '"')
#   box    x0 y0 z0 x1 y1 z1                       box between two opposite corners
#   block  cx y0 cz sx sy sz                       box centered on (cx, cz), from y0 up, size sx sy sz
#   stairs cx baseY startZ width steps rise run    `steps` (integer) solid steps climbing toward -Z
#   waffle x0 x1 y0 y1 z depth bayW floorH         facade: back wall (z-1..z) + fins every bayW
#                                                  + ledges every floorH, sticking out to z + depth
#
# Instead of many near-identical lines, put prefixes in front of a primitive:
#   repeat n dx dy dz      n copies, copy i shifted by i*(dx, dy, dz). Up to 3 repeats on one
#                          line make a grid; the first repeat is the outer loop.
#   at x y z               the primitive's coordinates are relative to (x, y, z)
# Shifts move positions only (box: all six numbers; block: cx y0 cz; stairs: cx baseY startZ;
# waffle: x0 x1 y0 y1 z), never sizes, steps or counts. `at` is only needed when exact float
# results matter (it reproduces the original C loops bit for bit); for new content, write
# the first copy's real coordinates and a repeat.
#
# Every box remembers the line it came from. Errors show as "file:line: message" in the HUD
# and the previous map stays loaded until the file is valid again.

group "ground"
box -400 -1 -400 400 0 400

# --- 1. Entry canyon: a narrow slot between two monumental walls ----------------------
group "entry canyon: walls"
box -4.5 0 40 -3 34 95
box  3   0 40  4.5 34 95

group "entry canyon: roof"
# roof segments 8.4 m long every 9 m, thin light slits between them; the last one is cut at z 95
repeat 6 0 0 9 at 0 0 40 box -4.5 34 0 4.5 36 8.4
box -4.5 34 94 4.5 36 95

group "entry canyon: back wall"
box -4.5 0 95 4.5 36 97                 # behind the player start

# --- 2. Hypostyle hall: forest of pillars under a slatted roof ------------------------
group "hypostyle hall: pillars"
# 2.2 x 2.2 x 20 m pillars on a 9 m grid, x -36..36, z -32..31, central axis (x = 0) kept free
repeat 4 9 0 0 repeat 8 0 0 9 block -36 0 -32 2.2 20 2.2
repeat 4 9 0 0 repeat 8 0 0 9 block   9 0 -32 2.2 20 2.2

group "hypostyle hall: roof"
# roof beams with gaps -> shafts of light through the volumetric fog
repeat 17 0 0 4.5 at 0 0 -36 box -40 20 0 40 22 2.6
box -40 22 -36 40 23 -30                # solid parts of the roof
box -40 22  30 40 23  39

group "hypostyle hall: cantilever"
box -14 23 -10 30 35 12                 # massive block hanging over the hall

group "hall east: chair"
# simple chair, 0.5 x 0.5 m seat at 0.45 m, backrest to 0.95 m on the -Z side (faces +Z)
repeat 2 0.44 0 0 repeat 2 0 0 0.44 box 45.95 0 2.55 46.01 0.4 2.61   # 4 legs, 6 x 6 cm
box 45.95 0.4 2.55 46.45 0.45 3.05      # seat
box 45.95 0.45 2.55 46.45 0.95 2.6      # backrest

group "hall east: table"
# 1.2 x 0.8 m table in front of the chair (its +Z side), top at 0.75 m
repeat 2 1.07 0 0 repeat 2 0 0 0.67 box 45.64 0 3.29 45.69 0.71 3.34   # 4 legs, 5 x 5 cm
box 45.6 0.71 3.25 46.8 0.75 4.05       # top, 4 cm thick

# --- 3. Monumental stairs up to the upper terrace ------------------------------------
group "monumental stairs"
stairs 0 0 -40 22 40 0.3 0.75           # 40 steps, rises 12 m
box -11.5 0 -40 -11 13 -70              # side walls
box  11   0 -40  11.5 13 -70

group "upper terrace"
box -60 0 -70 60 12 -140

# --- 4. Tower block with a waffle facade on the terrace ------------------------------
group "tower"
waffle -30 30 12 92 -100 2 4 4
box -30 12 -140 30 92 -101              # body
box -34 92 -142 34 96 -96               # crown slab

group "terrace pillar"
block 18 12 -82 1.2 6 1.2               # lone object in a big void

# --- 5. Distant megastructures, only silhouettes in the fog --------------------------
# each: a block, then 1 x 2 m fins every 6 m along its +Z face (x from -w/2 while <= w/2)
group "megastructures"
block -170 0 -120 60 180 70
repeat 11 6 0 0 block -200 0 -84 1 180 2
block 160 0 -180 90 240 60
repeat 16 6 0 0 block 115 0 -149 1 240 2
block -120 0 160 80 140 80
repeat 14 6 0 0 block -160 0 201 1 140 2
block 190 0 60 50 200 120
repeat 9 6 0 0 block 165 0 121 1 200 2
block 0 0 -300 220 120 40
repeat 37 6 0 0 block -110 0 -279 1 120 2
block -260 0 -20 40 260 40
repeat 7 6 0 0 block -280 0 1 1 260 2

group "bridge"
box -170 120 -152 160 128 -144          # between two megastructures, very high up
